function recorder(){return `<div class="tiny-label">ELENA’S RECORDINGS · 3 TAPES</div><p style="font-size:10px;color:#7a877f">Listen carefully. Some details are easier to hear than to explain.</p>${[['t1','Interview — J. Reed','OCT 13 · 4:08','“I never went back to the north station.”'],['t2','Rain at the flood gate','OCT 14 · 2:16','Three knocks. A pause. One knock. Then a voice under the rain: “Elena, don’t let me in.”'],['t3','Draft — personal','OCT 14 · 2:19','“If you hear this, the water has reached the second step. It always starts with my voice. It is not me.”']].map(([id,title,date,trans])=>`<div class="tape"><div class="tape-top"><span>▤ ${title}</span><span class="tiny-label">${date}</span></div><div class="wave"></div><button class="play" onclick="playTape('${id}',this)">▶</button> <span class="tiny-label">00:0${id==='t1'?'8':'6'}</span><div class="tape-transcript">${state.clues.has('audio')||id==='t1'?trans:'Transcript locked · play recording to reveal'}</div></div>`).join('')}<div class="system-note">AUDIO ENHANCEMENT: listen for the pattern beneath the rain.</div>`}
let audioContext;function playTape(id,button){if(id==='t2'||id==='t3'){state.clues.add('audio');if(id==='t3')unlockUnknown();notify(id==='t2'?'Enhanced: three knocks, pause, one.':'Elena warns you not to answer her voice.')}button.textContent='Ⅱ';try{audioContext=audioContext||new(window.AudioContext||window.webkitAudioContext)();const now=audioContext.currentTime;const knocks=id==='t2'?[0,.45,.9,1.9]:[0,.35,.7,1.7];knocks.forEach((delay,i)=>{const osc=audioContext.createOscillator(),gain=audioContext.createGain();osc.type='sine';osc.frequency.value= id==='t1'?180:95;gain.gain.setValueAtTime(.0001,now+delay);gain.gain.exponentialRampToValueAtTime(.22,now+delay+.01);gain.gain.exponentialRampToValueAtTime(.0001,now+delay+.14);osc.connect(gain);gain.connect(audioContext.destination);osc.start(now+delay);osc.stop(now+delay+.15)});setTimeout(()=>{button.textContent='▶';renderApp()},2600)}catch(e){setTimeout(()=>button.textContent='▶',1300)}renderApp()}
