function contacts(){return `<div class="tiny-label">CONTACTS · 3 SAVED / 1 UNSAVED</div><div class="contact-card"><div class="avatar">EV</div><div><b style="font-size:12px">Elena Voss</b><p>Owner · Investigative journalist<br>Last seen Oct 14, 2:17 AM</p></div></div><div class="contact-card"><div class="avatar">MB</div><div><b style="font-size:12px">Mara Bell</b><p>Childhood friend · Hollow Creek Historical Society<br>Known Elena since age 9</p></div></div><div class="contact-card"><div class="avatar">JR</div><div><b style="font-size:12px">Jonah Reed</b><p>Deputy · North Station<br>Dispatch supervisor, 1998 flood records</p></div></div><div class="contact-card"><div class="avatar" style="background:#f4e3df;color:#a3564d">?</div><div><b style="font-size:12px">Unknown Number</b><p>Caller ID withheld · Last call: Oct 14, 2:17 AM</p></div></div>`}
function map(){return `<div class="tiny-label">HOLLOW CREEK · COUNTY GRID 04</div><p style="font-size:10px;color:#77847c">The river divides the old town from what it took.</p><div class="map"><div class="river"></div><button class="place" style="top:20%;left:10%" onclick="place('North Station','The wall clock stopped at 2:17. Its dispatch log has a carbon copy.')">North Station</button><button class="place" style="top:46%;left:52%" onclick="place('Old Intake Gate','Exposed at low tide. Elena’s photograph shows fresh scratches.')">Intake Gate</button><button class="place" style="top:72%;left:8%" onclick="place('County Archive','Flood records list three names. Elena’s notes say there were four.')">County Archive</button><button class="place ${state.unlocked?'':'map-locked'}" style="top:12%;left:53%" onclick="place('Vale House','The Vale family disappeared after the 1998 flood. The house is empty.')">Vale House</button><button class="place" style="top:79%;left:55%" onclick="place('Bell Street Café','Two coffees, October 12. Mara and Elena met here.')">Bell Street</button></div><div id="place-info" class="system-note">Tap a marker to review location notes.</div>`}
function place(name,info){document.getElementById('place-info').innerHTML=`<b>${name}</b><br>${info}`}
function browser(){return `<div class="tiny-label">HOLLOW CREEK SEARCH · OFFLINE CACHE</div><div style="display:flex;gap:6px;margin:12px 0"><input class="searchbox" id="query" placeholder="Search local archives…" onkeydown="if(event.key==='Enter')search()"><button class="action-btn" onclick="search()">⌕</button></div><div id="search-results"><div class="result-link"><strong>Hollow Creek flood anniversary vigil</strong><small>HOLLOW CREEK GAZETTE · OCT 15, 2024</small><p>Twenty-six years after the flood, residents still disagree on how many people vanished. The official count remains three.</p></div><div class="result-link"><strong>Vale family home remains unoccupied</strong><small>COUNTY RECORD · OCT 14, 2024</small><p>June Vale, 17, was never found. Her mother Ruth was declared dead in 1999. No surviving next of kin.</p></div><div class="result-link"><strong>North station clock restored—again</strong><small>COMMUNITY BOARD · OCT 14, 2023</small><p>Town clock mysteriously stops at 2:17 each October 14. Maintenance reports no mechanical fault.</p></div></div>`}
function search(){const q=(document.getElementById('query')?.value||'').toLowerCase();const res=document.getElementById('search-results');if(!res)return;const items=[['THE FOURTH NAME: JUNE VALE','HOLLOW CREEK ARCHIVE · 1998','Witness statement mentions a fourth child at the intake gate. Every official transcript omits her.'],['THE FLOOD MARKER','LOCAL HISTORY · UPDATED OCT 14','The east marker reads 4. Town maps show it was chiseled down to 3 in 1999.'],['NORTH STATION DISPATCH RECORDS','COUNTY DOCUMENTS · OCT 14','Carbon copies are held under extension 031. Original audio missing.']];const found=items.filter(x=>!q||x.join(' ').toLowerCase().includes(q)||q.includes('flood')||q.includes('vale')||q.includes('station'));res.innerHTML=found.map(x=>`<div class="result-link"><strong>${x[0]}</strong><small>${x[1]}</small><p>${x[2]}</p></div>`).join('')||'<div class="system-note">No results. Try “flood”, “Vale”, or “station”.</div>';if(q.includes('vale')||q.includes('four'))state.clues.add('name')}
function unknown(){if(!state.unknown)return `<div class="unknown"><div class="tiny-label">APPLICATION NOT INSTALLED</div><p style="font-size:11px">This app appeared after the device synced.</p></div>`;return `<div class="unknown"><div class="tiny-label">NO SENDER · 2:17 AM</div><p class="ghost">${state.ending?'SIGNAL CLOSED. THE WATER IS QUIET.':'you are holding it wrong.'}<br><span class="glitch">I am not in the phone.</span><br>I am in the pause between rings.<br><br>${state.unlocked?'I only wanted someone to remember the fourth name.':'The gate is open. Do you hear it?'}</p>${state.ending?`<div class="ending">${state.ending==='answer'?'You sent one word: “June.” The typing indicator appeared. Then stopped. For the first time, Hollow Creek went quiet. You left the phone on the dry side of the river.':'You blocked the number. At dawn the signal vanished. The official story still says three. You know there were four.'}<br><b>ENDING: ${state.ending==='answer'?'THE NAME REMEMBERED':'THE QUIET BANK'}</b></div><button class="restart" onclick="location.reload()">Restart investigation</button>`:`<p style="font-size:10px;color:#a1b5a9">${state.unlocked?'A name is all I need.':'The water remembers what the records forgot.'}</p><div class="choices"><button class="choice" onclick="finish('answer')">${state.unlocked?'Send: JUNE VALE':'Answer the call'}</button><button class="choice" onclick="finish('refuse')">Block sender and end signal</button></div>`}</div>`}
